// CI fails when this file is stale against design/.

import SwiftUI
#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// The bundled families (docs/design/ui.md §4.1): Slipgates Sans and Slipgates Mono.
/// Every weight and style the ramps use is a real face, named here by its PostScript name, so
/// nothing is synthesized (ui.md §4.2). Ask for a weight or an italic through these rather than
/// applying `.bold()` or `.italic()` to another face. The files are registered by
/// SlipgatesFonts.plist: UIAppFonts on iOS and iPadOS, ATSApplicationFontsPath on macOS.
public enum SlipgatesFont {
    public enum Family: CaseIterable { case sans; case mono }

    public enum Weight: Int, CaseIterable {
        case regular = 400
        case medium = 500
        case semibold = 600
        case bold = 700
    }

    /// The PostScript name of a real face.
    public static func name(_ family: Family, _ weight: Weight = .regular, italic: Bool = false) -> String {
        switch (family, weight, italic) {
        case (.sans, .regular, false): return "SlipgatesSans"
        case (.sans, .regular, true): return "SlipgatesSansItalic"
        case (.sans, .medium, false): return "SlipgatesSans-Medium"
        case (.sans, .medium, true): return "SlipgatesSansItalic-Medium"
        case (.sans, .semibold, false): return "SlipgatesSans-SemiBold"
        case (.sans, .semibold, true): return "SlipgatesSansItalic-SemiBold"
        case (.sans, .bold, false): return "SlipgatesSans-Bold"
        case (.sans, .bold, true): return "SlipgatesSansItalic-Bold"
        case (.mono, .regular, false): return "SlipgatesMono-Regular"
        case (.mono, .regular, true): return "SlipgatesMono-Italic"
        case (.mono, .medium, false): return "SlipgatesMono-Medium"
        case (.mono, .medium, true): return "SlipgatesMono-MediumItalic"
        case (.mono, .semibold, false): return "SlipgatesMono-SemiBold"
        case (.mono, .semibold, true): return "SlipgatesMono-SemiBoldItalic"
        case (.mono, .bold, false): return "SlipgatesMono-Bold"
        case (.mono, .bold, true): return "SlipgatesMono-BoldItalic"
        }
    }

    /// SwiftUI: the face at a ramp size, scaled with Dynamic Type relative to `style`
    /// (UIFontMetrics underneath). macOS has no Dynamic Type, so there it stays at `size`.
    public static func font(_ family: Family, size: CGFloat, weight: Weight = .regular, italic: Bool = false, relativeTo style: Font.TextStyle = .body) -> Font {
        .custom(name(family, weight, italic: italic), size: size, relativeTo: style)
    }

#if canImport(UIKit)
    /// UIKit: the face, scaled for Dynamic Type by UIFontMetrics for `textStyle`. Set
    /// adjustsFontForContentSizeCategory on the view so it follows a change of setting.
    public static func uiFont(_ family: Family, size: CGFloat, weight: Weight = .regular, italic: Bool = false, textStyle: UIFont.TextStyle = .body) -> UIFont {
        let face = name(family, weight, italic: italic)
        guard let base = UIFont(name: face, size: size) else { preconditionFailure("\(face) is not registered: check UIAppFonts") }
        return UIFontMetrics(forTextStyle: textStyle).scaledFont(for: base)
    }
#elseif canImport(AppKit)
    /// AppKit: the face at a ramp size; macOS's ramp is fixed (ui.md §4.3).
    public static func nsFont(_ family: Family, size: CGFloat, weight: Weight = .regular, italic: Bool = false) -> NSFont {
        let face = name(family, weight, italic: italic)
        guard let font = NSFont(name: face, size: size) else { preconditionFailure("\(face) is not registered: check ATSApplicationFontsPath") }
        return font
    }
#endif

    /// Letter-spacing in em, by role (docs/design/ui.md §4.3): the title and the wordmark; every
    /// other role, body text above all, is untracked. Points at a size: em times the size the
    /// face is drawn at, after Dynamic Type, for SwiftUI's `.tracking(_:)` or a `.kern` attribute.
    public enum Tracking {
        public static let title: CGFloat = 0.02
        public static let wordmark: CGFloat = 0.02
        public static func points(_ em: CGFloat, size: CGFloat) -> CGFloat { em * size }
    }

    /// Every font file the app bundles, in its Fonts folder, as SlipgatesFonts.plist lists them.
    public static let files: [String] = [
        "SlipgatesSans.ttf",
        "SlipgatesSans-Italic.ttf",
        "SlipgatesMono-Regular.ttf",
        "SlipgatesMono-Italic.ttf",
        "SlipgatesMono-Medium.ttf",
        "SlipgatesMono-MediumItalic.ttf",
        "SlipgatesMono-SemiBold.ttf",
        "SlipgatesMono-SemiBoldItalic.ttf",
        "SlipgatesMono-Bold.ttf",
        "SlipgatesMono-BoldItalic.ttf",
    ]
}
